export class MethodWithArgs {
    method;
    args;
    kwargs;
    constructor(method, args, kwargs) {
        if (arguments.length < 3)
            throw new TypeError("MethodWithArgs.__init__() missing required arguments");
        this.method = method;
        this.args = args === undefined ? [] : Array.isArray(args) ? args : Array.from(args);
        this.kwargs = kwargs;
    }
}
